/* Timing workflow around the approved ruling-planet, transit and DBA engines. */
(()=>{'use strict';const $=id=>document.getElementById(id),DAY=86400000,CODES=['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'];
const presets={hours:{label:'2 hours',ms:2*3600000,planet:'As'},day:{label:'Day',ms:DAY,planet:'As'},week:{label:'Week',ms:7*DAY,planet:'Mo'},month:{label:'Month',months:1,planet:'Mo'},year:{label:'Year',months:12,planet:'Su'},years13:{label:'13 years',months:156,planet:'Ju'}};
let dialog,rp,rows=[],token=0,busy=false,last=null,focusRange=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function endOf(start,key){const p=presets[key];if(!p)throw Error('Choose a timing horizon.');if(p.ms)return new Date(+start+p.ms);const d=new Date(start),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+p.months);d.setUTCDate(Math.min(day,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));return d;}
function stamp(value,offset){return new Date(Date.parse(value)+offset*3600000).toISOString().replace('T',' ').slice(0,19);}
function houses(id){const row=currentKPModel?.fourfold?.planets?.find(p=>p.id===id);return [...new Set(['A','B','C','D'].flatMap(k=>row?.[k]||[]))];}
function requirements(){const text=$('rpf-houses').value.trim();if(!text)return [];if(!/^(?:[1-9]|1[0-2])(?:[\s,]+(?:[1-9]|1[0-2]))*$/.test(text))throw Error('Relevant houses must contain numbers 1–12.');return [...new Set(text.split(/[\s,]+/).map(Number))];}
function selectedRulers(){return [...dialog.querySelectorAll('[data-rpf-ruler]:checked:not(:disabled)')].map(n=>n.value);}
function source(){const value=$('rpf-query').value,offset=Number($('rpf-offset').value),latitude=KPDefaultLocation.coordinate($('rpf-lat').value),longitude=KPDefaultLocation.coordinate($('rpf-lon').value,true);if(!value||!Number.isFinite(offset)||offset< -14||offset>14||!Number.isFinite(latitude)||Math.abs(latitude)>=90||!Number.isFinite(longitude)||Math.abs(longitude)>180)throw Error('Enter a valid query time, UTC offset and location.');const query=new Date(Date.parse(value+'Z')-offset*3600000);if(!Number.isFinite(+query))throw Error('Enter a valid query date and time.');return {query,location:{latitude,longitude,timezone:offset,place:$('rpf-place').value||'Consultation place'}};}
function cancel(){token++;busy=false;if($('rpf-find'))$('rpf-find').disabled=false;if($('rpf-cancel'))$('rpf-cancel').hidden=true;}
function invalidate(){focusRange=null;if($('rpf-focus'))$('rpf-focus').textContent='';cancel();rows=[];last=null;$('rpf-results').replaceChildren();$('rpf-print').disabled=false;$('rpf-csv').disabled=true;$('rpf-status').textContent='Settings changed. Find matching times to update results.';}
function capture(){const s=source();rp=KPLiveRuling.calculate(s.query,s.location);const required=requirements(),filter=$('rpf-significators').checked&&required.length;const allowed=id=>!rp.excludedRulers.includes(id);const retained=rp.rulingPlanets.filter(id=>!filter||required.some(h=>houses(id).includes(h)));$('rpf-rulers').innerHTML=CODES.map(id=>'<label><input type="checkbox" data-rpf-ruler value="'+id+'" '+(retained.includes(id)?'checked':'')+(!allowed(id)?' disabled':'')+'>'+id+(rp.retrograde[id]&&!['Ra','Ke'].includes(id)?' ℞':'')+'</label>').join('');$('rpf-summary').textContent=rp.sources.map(s=>s.source+': '+s.planet).join(' · ');$('rpf-lsrd').textContent='L '+rp.points[0].sgl+' · S '+rp.points[1].stl+' · R '+rp.points[1].sgl+' · D '+(rp.dayLord||'unavailable')+' · Asc star '+rp.points[0].stl+' / sub '+rp.points[0].sl;return rp;}
function render(){const body=$('rpf-results');body.innerHTML='<table><thead><tr><th>Entry · local</th><th>Exit · exclusive</th><th>Timing planet · sign / star / sub at midpoint</th><th>MD / AD / PD</th><th>Refine</th></tr></thead><tbody>'+rows.slice(0,250).map((r,i)=>'<tr><td>'+esc(stamp(r.start,last.offset))+(r.startClipped?' · already active / clipped':'')+'</td><td>'+esc(stamp(r.end,last.offset))+'</td><td>'+esc(last.planet+' · '+r.chain.join(' / '))+'</td><td>'+esc(r.lords?.map(p=>p.id).join(' / ')||'Not applied')+'</td><td><button data-rpf-refine="'+i+'">Narrow time</button></td></tr>').join('')+'</tbody></table>';if(!rows.length)body.textContent='No interval satisfies all selected rules. Adjust the horizon, timing planet or selected RP.';$('rpf-print').disabled=false;$('rpf-csv').disabled=!rows.length;}
async function search(){if(busy)return;const own=++token;busy=true;$('rpf-find').disabled=true;$('rpf-cancel').hidden=false;rows=[];last=null;$('rpf-results').replaceChildren();$('rpf-print').disabled=false;$('rpf-csv').disabled=true;
try{const s=source();if(!rp||rp.utc!==s.query.toISOString()||['latitude','longitude','timezone','place'].some(k=>rp.location[k]!==s.location[k]))capture();const rulers=selectedRulers(),set=new Set(rulers),required=requirements(),planet=$('rpf-planet').value,key=$('rpf-range').value,start=focusRange?new Date(focusRange.start):s.query,end=new Date(Math.min(+endOf(start,key),focusRange?Date.parse(focusRange.end):Infinity)),fields=$('rpf-rule').value==='all'?['sgl','stl','sl']:['stl','sl'];if(!rulers.length)throw Error('Select at least one ruling planet.');if(planet==='As'&&end-start>2*DAY)throw Error('Ascendant timing is available for 2 hours or one day. Use Moon, Sun or Jupiter for longer horizons.');if($('rpf-dba').checked&&!required.length)throw Error('Choose an event or enter relevant houses before applying MD / AD / PD.');let periods=null;if($('rpf-dba').checked)periods=KPEventOutcome.periodMatches(currentKPModel,{method:'fourfold',strongest:false},{start,end},required);
 const tracks=[{id:'rpf',planet,label:'Selected ruling planets',levels:['sign','star','sub'],test:p=>fields.every(f=>set.has(p[f]))}];let found=[];
 if(!periods||periods.length)found=await KPTransit.scan({start,end,tracks,location:s.location,shouldCancel:()=>own!==token,onProgress:p=>{if(own===token)$('rpf-status').textContent='Searching '+presets[key].label+'… '+Math.round(p*100)+'%';}});
 if(own!==token)return;if(periods)found=KPEventOutcome.intersect(found,periods);last={offset:s.location.timezone,query:rp.utc,location:s.location,planet,parent:focusRange?structuredClone(focusRange):null,start:start.toISOString(),end:end.toISOString(),rulers,required,dba:!!periods,rule:fields.join(' + '),event:$('rpf-event').selectedOptions[0]?.textContent};rows=found.map(r=>{const mid=new Date((Date.parse(r.start)+Date.parse(r.end))/2),longitude=planet==='As'?KPTransitHouses.ascendant(mid,s.location.latitude,s.location.longitude):KPEphemeris.longitude(mid,planet),p=KPDisplay.longitudeDetails(longitude*3600);return {...r,chain:[p.sgl,p.stl,p.sl]};}).sort((a,b)=>a.start.localeCompare(b.start));render();$('rpf-status').textContent=rows.length+' matching intervals'+(rows.length>250?' · first 250 shown; CSV includes all':'')+' · '+presets[key].label+' · '+(periods?'MD, AD and PD support applied':'RP transit only')+'. Boundary refinement ≈1 second; astrological timing candidates, not confirmed events.';
}catch(e){if(own===token)$('rpf-status').textContent=e.message;}finally{if(own===token){busy=false;$('rpf-find').disabled=false;$('rpf-cancel').hidden=true;}}}
function refine(index){const row=rows[index];if(!row)return;const span=Date.parse(row.end)-Date.parse(row.start),planet=last.planet;focusRange={start:row.start,end:row.end,priorPlanet:planet};$('rpf-range').value=span<=2*3600000?'hours':span<=DAY?'day':span<=7*DAY?'week':span<=31*DAY?'month':'year';$('rpf-planet').value=span<=DAY?'As':span<=31*DAY?'Mo':'Su';$('rpf-focus').textContent='Refining '+stamp(row.start,last.offset)+' → '+stamp(row.end,last.offset)+' · inside prior '+planet+' match; original query RP retained.';search();}
function report(){try{const s=source(),data=last||{offset:s.location.timezone,query:s.query.toISOString(),location:s.location,rulers:selectedRulers(),rule:$('rpf-rule').selectedOptions[0].textContent,required:requirements(),event:$('rpf-event').selectedOptions[0]?.textContent};let preview=$('rpf-preview');if(!preview){preview=document.createElement('dialog');preview.id='rpf-preview';preview.innerHTML='<header class="rpf-preview-tools"><strong>A4 report preview</strong><button type="button" data-rpf-zoom="in">Zoom +</button><button type="button" data-rpf-zoom="out">Zoom −</button><button type="button" data-rpf-zoom="fit">Fit</button><button type="button" data-rpf-print>Print / Save PDF</button><button type="button" data-rpf-close>Close</button></header><article class="rpf-paper"></article>';document.body.append(preview);preview.querySelector('[data-rpf-close]').onclick=()=>preview.close();preview.querySelector('[data-rpf-print]').onclick=()=>window.print();let zoom=1;preview.querySelectorAll('[data-rpf-zoom]').forEach(b=>b.onclick=()=>{zoom=b.dataset.rpfZoom==='fit'?Math.min(1,(preview.clientWidth-24)/750):Math.max(.4,Math.min(2,zoom+(b.dataset.rpfZoom==='in'?.1:-.1)));preview.querySelector('.rpf-paper').style.zoom=zoom;});}const box=$('rpf-results').cloneNode(true);box.querySelectorAll('button').forEach(b=>b.remove());preview.querySelector('.rpf-paper').innerHTML='<h1>Ruling Planet · Event timing</h1><p>'+esc(data.event)+' · Query '+esc(stamp(data.query,data.offset))+' · '+esc(data.location.place)+' · '+esc(KPDefaultLocation.dms(data.location.latitude))+' / '+esc(KPDefaultLocation.dms(data.location.longitude,true))+' · UTC '+data.offset+'</p><p>'+esc($('rpf-focus').textContent)+'</p><p>'+esc($('rpf-lsrd').textContent)+'</p><p>Selected RP: '+esc(data.rulers.join(', '))+' · Rule: '+esc(data.rule)+' · Houses: '+data.required.join(', ')+'</p>'+(last?'<p>'+esc($('rpf-status').textContent)+'</p>'+box.innerHTML:'<p>No calculated results yet. Close this preview and select Find matching times to calculate candidate intervals.</p>')+(rows.length>250?'<p>First 250 intervals shown. Export CSV for the complete list.</p>':'');if(!preview.open)preview.showModal();}catch(e){$('rpf-status').textContent='Preview: '+e.message;}}
function csv(){if(!last)return;const values=[['Entry local','Exit exclusive local','Planet','Sign lord','Star lord','Sub lord','MD/AD/PD','UTC offset'],...rows.map(r=>[stamp(r.start,last.offset),stamp(r.end,last.offset),last.planet,...r.chain,r.lords?.map(p=>p.id).join('/')||'',last.offset])],blob=new Blob(['\ufeff'+values.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='KP-Ruling-Planet-Timing.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function now(){const loc=KPDefaultLocation.get(),offset=Number(loc.timezone??loc.utcOffset??5.5);$('rpf-offset').value=offset;$('rpf-query').value=new Date(Date.now()+offset*3600000).toISOString().slice(0,19);$('rpf-lat').value=KPDefaultLocation.dms(loc.latitude);$('rpf-lon').value=KPDefaultLocation.dms(loc.longitude,true);$('rpf-place').value=loc.place||'';invalidate();capture();}
function init(){dialog=document.createElement('dialog');dialog.id='kp-ruling-finder';dialog.innerHTML='<header><h2>Ruling Planet · Event Time Finder</h2><button id="rpf-close" aria-label="Close">×</button></header><div class="rpf-controls"><label>Query / RP local time<input id="rpf-query" type="datetime-local" step="1"></label><button id="rpf-now">Now</button><label>Horizon<select id="rpf-range">'+Object.entries(presets).map(([key,p])=>'<option value="'+key+'">'+p.label+'</option>').join('')+'</select></label><label>Timing planet<select id="rpf-planet"><option value="As">Ascendant · hours</option><option value="Mo">Moon · days / weeks</option><option value="Su">Sun · months</option><option value="Ju">Jupiter · years</option></select></label></div><div id="rpf-lsrd"></div><p id="rpf-summary"></p><fieldset><legend>Selected ruling planets · editable</legend><div id="rpf-rulers"></div></fieldset><div class="rpf-controls"><label class="rpf-event">Event<select id="rpf-event"><option value="">RP transit only</option></select></label><label>Relevant houses<input id="rpf-houses" placeholder="2, 7, 11"></label><label>Transit match<select id="rpf-rule"><option value="all">Sign AND star AND sub in RP</option><option value="starsub">Star AND sub in RP</option></select></label></div><div class="rpf-checks"><label><input id="rpf-dba" type="checkbox">Require all MD / AD / PD event support</label><label><input id="rpf-significators" type="checkbox">Keep RP signifying event houses</label></div><details><summary>Location &amp; timing method</summary><div class="rpf-controls rpf-location-controls"><label>Place<input id="rpf-place"></label><label>Latitude · D:M:S<input id="rpf-lat" type="text" placeholder="18:00:00 N"></label><label>Longitude · D:M:S<input id="rpf-lon" type="text" placeholder="73:00:00 E"></label><label>UTC offset<input id="rpf-offset" type="number" step="any" min="-14" max="14"></label></div><p>RP are fixed at the query time: Ascendant sign/star, Moon sign/star and sunrise-based day lord. Timing planets are search presets; their use across horizons is a workflow choice, not a separate guaranteed KP formula. Long searches give broad candidate windows; use a shorter horizon for finer timing. Retrograde markers are shown for review. Original KP ayanamsha and existing transit boundary engine are used.</p></details><footer><button id="rpf-find">Find matching times</button><button id="rpf-cancel" hidden>Cancel</button><button id="rpf-print">A4 Preview / Print</button><button id="rpf-csv" disabled>CSV</button></footer><p id="rpf-focus"></p><p id="rpf-status" role="status"></p><div id="rpf-results"></div>';
 document.body.append(dialog);for(const e of KPPrediction.getCatalogue().events)$('rpf-event').append(new Option(e.event.en||e.event.mr,String(e.id)));window.KPIndiaPlaces?.attach({placeId:'rpf-place',latId:'rpf-lat',lonId:'rpf-lon',offsetId:'rpf-offset',format:'dms'});$('rpf-close').onclick=()=>dialog.close();dialog.addEventListener('close',cancel);dialog.addEventListener('cancel',cancel);$('rpf-now').onclick=now;$('rpf-find').onclick=search;$('rpf-cancel').onclick=()=>{cancel();$('rpf-status').textContent='Search cancelled.';};$('rpf-print').onclick=report;$('rpf-csv').onclick=csv;$('rpf-results').addEventListener('click',e=>{const b=e.target.closest('[data-rpf-refine]');if(b)refine(Number(b.dataset.rpfRefine));});
 dialog.addEventListener('change',e=>{invalidate();if(e.target.id==='rpf-range')$('rpf-planet').value=presets[e.target.value].planet;if(e.target.id==='rpf-event'){const event=KPPrediction.getCatalogue().events.find(x=>String(x.id)===e.target.value);$('rpf-houses').value=event?[...new Set([...(event.mainHouses||[]),...(event.relevantHouses||[]),...(event.supportingHouses||[]),...(event.supportingGroups||[]).flat()])].filter(h=>Number.isInteger(h)&&h>=1&&h<=12).sort((a,b)=>a-b).join(', '):'';$('rpf-dba').checked=!!event;$('rpf-significators').checked=!!event;}
 if(!e.target.matches('[data-rpf-ruler]'))try{capture();}catch(error){$('rpf-status').textContent=error.message;}});dialog.addEventListener('input',e=>{if(e.target.matches('input:not([type=checkbox])'))invalidate();});
}
function open(){if(!dialog)init();if(!dialog.open)dialog.showModal();try{now();}catch(e){$('rpf-status').textContent=e.message;}}
window.addEventListener('kp-preferences-changed',()=>{if(dialog?.open){invalidate();try{capture();}catch(e){$('rpf-status').textContent=e.message;}}});
window.KPRulingFinder=Object.freeze({open,search,cancel,endOf,presets:()=>structuredClone(presets),getResults:()=>structuredClone(rows),source,now});
})();
